PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE intents (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL, docker_id TEXT, github_runner_id TEXT, cleanup_proven INTEGER NOT NULL DEFAULT 0, dind_id TEXT, launch_id TEXT, assignment_key TEXT, seed_generation_id TEXT, acquire_attempted INTEGER NOT NULL DEFAULT 0, acquire_resolved INTEGER NOT NULL DEFAULT 0, acquired INTEGER NOT NULL DEFAULT 0, jit_requested INTEGER NOT NULL DEFAULT 0, runner_completed INTEGER NOT NULL DEFAULT 0, worker_cleanup_proven INTEGER NOT NULL DEFAULT 0, worker_volume TEXT, scale_set_id INTEGER, runner_request_id INTEGER, runner_name TEXT, docker_engine_id TEXT, launch_phase TEXT);
CREATE TABLE journal_meta (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), instance_id TEXT NOT NULL, engine_id TEXT, revision INTEGER NOT NULL DEFAULT 0, lineage_pinned INTEGER NOT NULL DEFAULT 0);
INSERT INTO journal_meta VALUES(1,'6293cd191f3c48b682b6679d2ab55b44',NULL,0,0);
CREATE TABLE resource_probe_operations (operation_id TEXT PRIMARY KEY CHECK(length(operation_id) = 32 AND operation_id NOT GLOB '*[^0-9a-f]*'), instance_id TEXT NOT NULL, engine_id TEXT NOT NULL, docker_root_digest TEXT NOT NULL CHECK(length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), source_revision TEXT NOT NULL CHECK(length(source_revision) = 40 AND source_revision NOT GLOB '*[^0-9a-f]*'), runtime_image_id TEXT NOT NULL, image_binding_digest TEXT NOT NULL CHECK(length(image_binding_digest) = 64 AND image_binding_digest NOT GLOB '*[^0-9a-f]*'), operation_name TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role = 'resource-probe'), projection_digest TEXT NOT NULL CHECK(length(projection_digest) = 64 AND projection_digest NOT GLOB '*[^0-9a-f]*'), phase TEXT NOT NULL CHECK(phase IN ('prepared', 'create_requested', 'container_created', 'start_requested', 'started', 'wait_requested', 'waited', 'logs_requested', 'output_observed', 'stop_requested', 'remove_requested', 'removed', 'aborted', 'quarantined')), container_id TEXT, helper_role TEXT NOT NULL DEFAULT 'resource-probe' CHECK(helper_role IN ('resource-probe', 'execution-publication')), probe_purpose TEXT NOT NULL DEFAULT 'capacity' CHECK(probe_purpose IN ('capacity', 'owned-cgroups', 'cleanup-observer', 'none')), request_sha256 TEXT CHECK(request_sha256 IS NULL OR (length(request_sha256) = 64 AND request_sha256 NOT GLOB '*[^0-9a-f]*')), request_context TEXT CHECK(request_context IS NULL OR ((probe_purpose = 'cleanup-observer' AND length(CAST(request_context AS BLOB)) <= 32768) OR (probe_purpose != 'cleanup-observer' AND length(CAST(request_context AS BLOB)) <= 8192))));
CREATE TABLE host_operation_leases (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), operation_id TEXT NOT NULL UNIQUE CHECK (length(operation_id) = 32 AND operation_id NOT GLOB '*[^0-9a-f]*'), engine_id TEXT NOT NULL CHECK (length(engine_id) BETWEEN 1 AND 256), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), operation_name TEXT NOT NULL UNIQUE CHECK (length(operation_name) BETWEEN 1 AND 255), container_id TEXT CHECK (container_id IS NULL OR (length(container_id) = 64 AND container_id NOT GLOB '*[^0-9a-f]*')), cpu_millicores INTEGER NOT NULL CHECK (cpu_millicores > 0), memory_bytes INTEGER NOT NULL CHECK (memory_bytes > 0), state TEXT NOT NULL CHECK (state IN ('reserved', 'active', 'uncertain', 'recovering', 'released')));
CREATE TABLE completion_cleanup (intent_id INTEGER PRIMARY KEY REFERENCES intents (id), scale_set_id INTEGER NOT NULL, runner_request_id INTEGER NOT NULL, runner_id INTEGER NOT NULL, runner_name TEXT NOT NULL, runner_absent INTEGER NOT NULL DEFAULT 0 CHECK (runner_absent IN (0, 1)), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), claim_generation INTEGER NOT NULL DEFAULT 0 CHECK (claim_generation >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0), UNIQUE (scale_set_id, runner_request_id), UNIQUE (scale_set_id, runner_id), UNIQUE (scale_set_id, runner_name));
CREATE TABLE completion_inbox (scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), message_id INTEGER NOT NULL CHECK (message_id >= 0), raw_body TEXT NOT NULL CHECK (length(CAST(raw_body AS BLOB)) BETWEEN 1 AND 262144), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), PRIMARY KEY (scale_set_id, message_id));
CREATE TABLE launch_recovery (intent_id INTEGER PRIMARY KEY REFERENCES intents (id), generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0));
CREATE TABLE guest_probe_owner (id INTEGER PRIMARY KEY CHECK (id = 1), owner_token TEXT NOT NULL CHECK (length(owner_token) = 32 AND owner_token NOT GLOB '*[^0-9a-f]*'));
CREATE TABLE connection_scopes (connection_id TEXT NOT NULL PRIMARY KEY CHECK (length(connection_id) BETWEEN 1 AND 64 AND connection_id NOT GLOB '*[^a-z0-9._-]*' AND substr(connection_id, 1, 1) != '-' AND substr(connection_id, -1, 1) != '-' AND instr(connection_id, '..') = 0), identity TEXT NOT NULL CHECK (length(CAST(identity AS BLOB)) BETWEEN 1 AND 1048576), retired INTEGER NOT NULL DEFAULT 0 CHECK (retired IN (0, 1)));
CREATE TABLE connection_intents (id INTEGER PRIMARY KEY AUTOINCREMENT, connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), kind TEXT NOT NULL, subject TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('pending', 'done', 'uncertain', 'failed')), cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (cleanup_proven IN (0, 1)), docker_id TEXT, github_runner_id TEXT, dind_id TEXT, worker_volume TEXT, scale_set_id INTEGER, runner_request_id INTEGER, runner_name TEXT, acquire_attempted INTEGER NOT NULL DEFAULT 0 CHECK (acquire_attempted IN (0, 1)), acquire_resolved INTEGER NOT NULL DEFAULT 0 CHECK (acquire_resolved IN (0, 1)), acquired INTEGER NOT NULL DEFAULT 0 CHECK (acquired IN (0, 1)), jit_requested INTEGER NOT NULL DEFAULT 0 CHECK (jit_requested IN (0, 1)), docker_engine_id TEXT, launch_phase TEXT, launch_id TEXT, assignment_key TEXT, seed_generation_id TEXT, runner_completed INTEGER NOT NULL DEFAULT 0 CHECK (runner_completed IN (0, 1)), worker_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (worker_cleanup_proven IN (0, 1)));
CREATE TABLE host_capacity_policy (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), max_jobs INTEGER NOT NULL CHECK (max_jobs > 0), max_cpu_millicores INTEGER NOT NULL CHECK (max_cpu_millicores > 0), max_memory_bytes INTEGER NOT NULL CHECK (max_memory_bytes > 0), operational_cpu_millicores INTEGER NOT NULL DEFAULT 0 CHECK (operational_cpu_millicores >= 0), operational_memory_bytes INTEGER NOT NULL DEFAULT 0 CHECK (operational_memory_bytes >= 0));
CREATE TABLE capacity_reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, intent_id INTEGER NOT NULL REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), assignment_key TEXT NOT NULL CHECK (length(assignment_key) BETWEEN 1 AND 1024), engine_id TEXT NOT NULL CHECK (length(engine_id) BETWEEN 1 AND 128), docker_root_digest TEXT NOT NULL CHECK (length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), binding_digest TEXT NOT NULL CHECK (length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), sample_generation_id TEXT, cpu_millicores INTEGER NOT NULL CHECK (cpu_millicores > 0), memory_bytes INTEGER NOT NULL CHECK (memory_bytes > 0), state TEXT NOT NULL CHECK (state IN ('reserved', 'uncertain', 'recovering', 'released')), remote_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (remote_cleanup_proven IN (0, 1)), local_cleanup_proven INTEGER NOT NULL DEFAULT 0 CHECK (local_cleanup_proven IN (0, 1)), CHECK (state != 'released' OR (remote_cleanup_proven = 1 AND local_cleanup_proven = 1)));
CREATE TABLE capacity_reservation_samples (reservation_id INTEGER NOT NULL REFERENCES capacity_reservations (id), sample_generation_id TEXT NOT NULL UNIQUE CHECK (length(sample_generation_id) = 32 AND sample_generation_id NOT GLOB '*[^0-9a-f]*'), purpose TEXT NOT NULL CHECK (purpose IN ('initial', 'resume')), PRIMARY KEY (reservation_id, sample_generation_id));
CREATE TABLE connection_runtime_bindings (connection_id TEXT NOT NULL PRIMARY KEY REFERENCES connection_scopes (connection_id), scale_set_id INTEGER, scale_set_name TEXT, set_ownership TEXT CHECK (set_ownership IS NULL OR set_ownership IN ('created', 'adopted')), engine_id TEXT, docker_endpoint TEXT, platform TEXT, CHECK ((scale_set_id IS NULL AND scale_set_name IS NULL AND set_ownership IS NULL) OR (scale_set_id > 0 AND length(scale_set_name) BETWEEN 1 AND 128 AND set_ownership IS NOT NULL)), CHECK ((engine_id IS NULL AND docker_endpoint IS NULL AND platform IS NULL) OR (length(engine_id) BETWEEN 1 AND 128 AND length(docker_endpoint) BETWEEN 1 AND 4096 AND length(platform) BETWEEN 1 AND 64)));
CREATE TABLE connection_completion_cleanup (intent_id INTEGER PRIMARY KEY REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), runner_request_id INTEGER NOT NULL CHECK (runner_request_id > 0), runner_id INTEGER NOT NULL CHECK (runner_id > 0), runner_name TEXT NOT NULL, runner_absent INTEGER NOT NULL DEFAULT 0 CHECK (runner_absent IN (0, 1)), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), claim_generation INTEGER NOT NULL DEFAULT 0 CHECK (claim_generation >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0), UNIQUE (connection_id, scale_set_id, runner_request_id), UNIQUE (connection_id, scale_set_id, runner_id), UNIQUE (connection_id, scale_set_id, runner_name));
CREATE TABLE connection_completion_inbox (connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), message_id INTEGER NOT NULL CHECK (message_id >= 0), raw_body TEXT NOT NULL CHECK (length(CAST(raw_body AS BLOB)) BETWEEN 1 AND 262144), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), PRIMARY KEY (connection_id, scale_set_id, message_id));
CREATE TABLE connection_launch_recovery (intent_id INTEGER PRIMARY KEY REFERENCES connection_intents (id), connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), generation INTEGER NOT NULL DEFAULT 0 CHECK (generation >= 0), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), retry_after INTEGER NOT NULL DEFAULT 0 CHECK (retry_after >= 0), lease_until INTEGER NOT NULL DEFAULT 0 CHECK (lease_until >= 0));
CREATE TABLE image_imports (id INTEGER PRIMARY KEY AUTOINCREMENT, engine_id TEXT NOT NULL, docker_root_digest TEXT NOT NULL CHECK(length(docker_root_digest) = 64 AND docker_root_digest NOT GLOB '*[^0-9a-f]*'), daemon_architecture TEXT NOT NULL CHECK(daemon_architecture IN ('x86_64', 'aarch64')), source_sha TEXT NOT NULL CHECK(length(source_sha) = 40 AND source_sha NOT GLOB '*[^0-9a-f]*'), archive_sha256 TEXT NOT NULL CHECK(length(archive_sha256) = 64 AND archive_sha256 NOT GLOB '*[^0-9a-f]*'), index_digest TEXT NOT NULL CHECK(length(index_digest) = 64 AND index_digest NOT GLOB '*[^0-9a-f]*'), platform TEXT NOT NULL CHECK(platform = 'linux/amd64'), manifest_digest TEXT NOT NULL CHECK(length(manifest_digest) = 71 AND substr(manifest_digest, 1, 7) = 'sha256:' AND substr(manifest_digest, 8) NOT GLOB '*[^0-9a-f]*'), config_digest TEXT NOT NULL CHECK(length(config_digest) = 71 AND substr(config_digest, 1, 7) = 'sha256:' AND substr(config_digest, 8) NOT GLOB '*[^0-9a-f]*'), attempt INTEGER NOT NULL CHECK(attempt >= 0), state TEXT NOT NULL CHECK(state IN ('prepared', 'requested', 'uncertain', 'completed', 'aborted')), image_id TEXT, image_index_digest TEXT CHECK(image_index_digest IS NULL OR (length(image_index_digest) = 71 AND substr(image_index_digest, 1, 7) = 'sha256:' AND substr(image_index_digest, 8) NOT GLOB '*[^0-9a-f]*')), image_index_size INTEGER CHECK(image_index_size IS NULL OR image_index_size > 0), manifest_size INTEGER CHECK(manifest_size IS NULL OR manifest_size > 0), load_archive_sha256 TEXT CHECK(load_archive_sha256 IS NULL OR (length(load_archive_sha256) = 64 AND load_archive_sha256 NOT GLOB '*[^0-9a-f]*')), load_archive_index_digest TEXT CHECK(load_archive_index_digest IS NULL OR (length(load_archive_index_digest) = 64 AND load_archive_index_digest NOT GLOB '*[^0-9a-f]*')), image_reference TEXT CHECK(image_reference IS NULL OR (length(image_reference) BETWEEN 1 AND 255 AND image_reference NOT GLOB '*[^a-z0-9:-]*')), receipt TEXT, CHECK((state = 'completed' AND image_id IS NOT NULL) OR (state != 'completed' AND image_id IS NULL)), UNIQUE (engine_id, docker_root_digest, daemon_architecture, source_sha, archive_sha256, index_digest, platform, manifest_digest, config_digest, attempt));
CREATE TABLE connection_scale_set_intents (id INTEGER PRIMARY KEY AUTOINCREMENT, connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), binding_digest TEXT NOT NULL CHECK (length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), repository_id INTEGER NOT NULL CHECK (repository_id > 0), repository TEXT NOT NULL CHECK (length(repository) BETWEEN 3 AND 201), selector_name TEXT NOT NULL CHECK (length(selector_name) BETWEEN 1 AND 64), selector_labels TEXT NOT NULL CHECK (length(CAST(selector_labels AS BLOB)) BETWEEN 1 AND 4096), runner_group_id INTEGER NOT NULL CHECK (runner_group_id > 0), state TEXT NOT NULL CHECK (state IN ('prepared', 'requested', 'uncertain', 'no_effect', 'created', 'adopted')), no_effect_status INTEGER, remote_id INTEGER, remote_name TEXT, remote_labels TEXT, disable_update INTEGER, ownership TEXT CHECK (ownership IS NULL OR ownership IN ('created', 'adopted')), CHECK ((state = 'no_effect' AND no_effect_status = 409 AND remote_id IS NULL AND remote_name IS NULL AND remote_labels IS NULL AND disable_update IS NULL AND ownership IS NULL) OR (state IN ('prepared', 'requested', 'uncertain') AND no_effect_status IS NULL AND remote_id IS NULL AND remote_name IS NULL AND remote_labels IS NULL AND disable_update IS NULL AND ownership IS NULL) OR (state IN ('created', 'adopted') AND (no_effect_status IS NULL OR (state = 'adopted' AND no_effect_status = 409)) AND remote_id > 0 AND remote_name = selector_name AND remote_labels IS NOT NULL AND disable_update = 1 AND ownership = state)), UNIQUE (connection_id));
CREATE TABLE connection_source_authorizations (connection_id TEXT NOT NULL, scale_set_id INTEGER NOT NULL CHECK(scale_set_id > 0), request_id INTEGER NOT NULL CHECK(request_id > 0), intent_id INTEGER NOT NULL UNIQUE, message_id INTEGER NOT NULL CHECK(message_id >= 0), policy_mode TEXT NOT NULL CHECK(policy_mode IN ('repository', 'branch_restricted')), authority_model TEXT NOT NULL CHECK(authority_model = 'created_empty_exclusive_admin_session_v1'), binding_digest TEXT NOT NULL CHECK(length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), source_digest TEXT NOT NULL CHECK(length(source_digest) = 64 AND source_digest NOT GLOB '*[^0-9a-f]*'), source_json TEXT NOT NULL CHECK(length(CAST(source_json AS BLOB)) BETWEEN 1 AND 32768), receipt_binding_digest TEXT CHECK(receipt_binding_digest IS NULL OR (length(receipt_binding_digest) = 64 AND receipt_binding_digest NOT GLOB '*[^0-9a-f]*')), PRIMARY KEY (connection_id, scale_set_id, request_id), FOREIGN KEY (connection_id) REFERENCES connection_scopes(connection_id), FOREIGN KEY (intent_id) REFERENCES connection_intents(id));
CREATE TABLE connection_request_authorizations (connection_id TEXT NOT NULL REFERENCES connection_scopes (connection_id), scale_set_id INTEGER NOT NULL CHECK (scale_set_id > 0), request_id INTEGER NOT NULL CHECK (request_id > 0), message_id INTEGER NOT NULL CHECK (message_id >= 0), policy_mode TEXT NOT NULL CHECK (policy_mode IN ('repository', 'branch_restricted')), authority_model TEXT NOT NULL CHECK (authority_model = 'created_empty_exclusive_admin_session_v1'), binding_digest TEXT NOT NULL CHECK (length(binding_digest) = 64 AND binding_digest NOT GLOB '*[^0-9a-f]*'), source_digest TEXT NOT NULL CHECK (length(source_digest) = 64 AND source_digest NOT GLOB '*[^0-9a-f]*'), source_json TEXT NOT NULL CHECK (length(CAST(source_json AS BLOB)) BETWEEN 1 AND 32768), acquire_state TEXT NOT NULL CHECK (acquire_state IN ('authorized', 'requested', 'acquired', 'no_effect', 'already_acquired', 'rejected', 'uncertain')), acquire_response_json TEXT CHECK (acquire_response_json IS NULL OR length(CAST(acquire_response_json AS BLOB)) <= 4096), acquire_response_digest TEXT CHECK (acquire_response_digest IS NULL OR (length(acquire_response_digest) = 64 AND acquire_response_digest NOT GLOB '*[^0-9a-f]*')), started_message_id INTEGER CHECK (started_message_id IS NULL OR started_message_id >= 0), started_event_digest TEXT CHECK (started_event_digest IS NULL OR (length(started_event_digest) = 64 AND started_event_digest NOT GLOB '*[^0-9a-f]*')), started_job_id TEXT CHECK (started_job_id IS NULL OR length(CAST(started_job_id AS BLOB)) <= 256), started_runner_id INTEGER CHECK (started_runner_id IS NULL OR started_runner_id > 0), started_runner_name TEXT CHECK (started_runner_name IS NULL OR length(CAST(started_runner_name AS BLOB)) BETWEEN 1 AND 128), completed_message_id INTEGER CHECK (completed_message_id IS NULL OR completed_message_id >= 0), completed_event_digest TEXT CHECK (completed_event_digest IS NULL OR (length(completed_event_digest) = 64 AND completed_event_digest NOT GLOB '*[^0-9a-f]*')), completed_job_id TEXT CHECK (completed_job_id IS NULL OR length(CAST(completed_job_id AS BLOB)) <= 256), completed_result TEXT CHECK (completed_result IS NULL OR length(CAST(completed_result AS BLOB)) <= 128), completed_runner_id INTEGER CHECK (completed_runner_id IS NULL OR completed_runner_id > 0), completed_runner_name TEXT CHECK (completed_runner_name IS NULL OR length(CAST(completed_runner_name AS BLOB)) BETWEEN 1 AND 128), completed_intent_id INTEGER REFERENCES connection_intents (id), PRIMARY KEY (connection_id, scale_set_id, request_id), CHECK ((acquire_state IN ('authorized', 'requested') AND acquire_response_json IS NULL AND acquire_response_digest IS NULL) OR (acquire_state NOT IN ('authorized', 'requested') AND acquire_response_json IS NOT NULL AND acquire_response_digest IS NOT NULL)), CHECK ((started_event_digest IS NULL AND started_message_id IS NULL AND started_job_id IS NULL AND started_runner_id IS NULL AND started_runner_name IS NULL) OR (started_event_digest IS NOT NULL AND started_message_id IS NOT NULL AND started_runner_id IS NOT NULL AND started_runner_name IS NOT NULL)), CHECK ((completed_event_digest IS NULL AND completed_message_id IS NULL AND completed_job_id IS NULL AND completed_result IS NULL AND completed_runner_id IS NULL AND completed_runner_name IS NULL AND completed_intent_id IS NULL) OR (completed_event_digest IS NOT NULL AND completed_message_id IS NOT NULL AND ((completed_runner_id IS NULL AND completed_runner_name IS NULL AND completed_intent_id IS NULL) OR (completed_runner_id IS NOT NULL AND completed_runner_name IS NOT NULL AND completed_intent_id IS NOT NULL)))));
