CREATE TABLE host_storage_profiles (generation_id TEXT NOT NULL PRIMARY KEY CHECK (length(generation_id) = 32 AND generation_id NOT GLOB '*[^0-9a-f]*'), profile_digest TEXT NOT NULL CHECK (length(profile_digest) = 64 AND profile_digest NOT GLOB '*[^0-9a-f]*'));
CREATE TABLE host_storage_profile_publication (generation_id TEXT NOT NULL PRIMARY KEY REFERENCES host_storage_profiles (generation_id), policy_digest TEXT NOT NULL CHECK (length(policy_digest) = 64 AND policy_digest NOT GLOB '*[^0-9a-f]*'));
