CREATE TABLE host_storage_profile_roles (generation_id TEXT NOT NULL REFERENCES host_storage_profiles (generation_id), role TEXT NOT NULL CHECK (role IN ('runner-root', 'runner-home', 'runner-work', 'runner-tmp', 'runner-shm', 'shared-run', 'dind-root', 'dind-data', 'dind-tmp', 'dind-shm', 'cache-live', 'cache-stage', 'engine-metadata')), pool_id TEXT NOT NULL CHECK (length(pool_id) = 64 AND pool_id NOT GLOB '*[^0-9a-f]*'), medium TEXT NOT NULL CHECK (medium IN ('disk', 'tmpfs')), max_bytes INTEGER NOT NULL CHECK (max_bytes >= 0), max_inodes INTEGER NOT NULL CHECK (max_inodes >= 0), retained_memory_bytes INTEGER NOT NULL CHECK (retained_memory_bytes >= 0), alias_of TEXT CHECK (alias_of IS NULL OR (alias_of IN ('runner-root', 'runner-home', 'runner-work', 'runner-tmp', 'runner-shm', 'shared-run', 'dind-root', 'dind-data', 'dind-tmp', 'dind-shm', 'cache-live', 'cache-stage', 'engine-metadata') AND alias_of != role)), CHECK ((alias_of IS NULL AND role NOT IN ('cache-live', 'cache-stage') AND max_bytes > 0 AND max_inodes > 0 AND ((medium = 'disk' AND retained_memory_bytes = 0) OR (medium = 'tmpfs' AND retained_memory_bytes = max_bytes))) OR (alias_of = 'runner-work' AND role IN ('cache-live', 'cache-stage') AND max_bytes > 0 AND max_inodes > 0 AND retained_memory_bytes = 0)), PRIMARY KEY (generation_id, role), FOREIGN KEY (generation_id, pool_id) REFERENCES host_storage_profile_pools (generation_id, pool_id), FOREIGN KEY (generation_id, alias_of) REFERENCES host_storage_profile_roles (generation_id, role));
