CREATE TABLE capacity_reservation_bound_storage_paths (reservation_id INTEGER NOT NULL, role TEXT NOT NULL, observer TEXT NOT NULL, mount_target TEXT NOT NULL, mount_root TEXT NOT NULL CHECK (length (mount_root) BETWEEN 1 AND 512), statx_inode INTEGER CHECK (statx_inode IS NULL OR statx_inode > 0), volume_subpath TEXT, PRIMARY KEY (reservation_id, role, observer, mount_target), FOREIGN KEY (reservation_id, role, observer, mount_target) REFERENCES capacity_reservation_bound_storage_attachments (reservation_id, role, observer, mount_target), CHECK ((role = 'engine-metadata' AND observer = 'runner' AND ((mount_target = '/.velnor-runtime-identity' AND volume_subpath IS 'runtime-identity') OR (mount_target = '/opt/velnor/job-facts' AND volume_subpath IS 'job-facts') OR (mount_target = '/opt/velnor/source-proof/control' AND volume_subpath IS 'source-proof/control') OR (mount_target = '/opt/velnor/source-proof/inbox' AND volume_subpath IS 'source-proof/inbox'))) OR (role = 'engine-metadata' AND observer = 'dind' AND ((mount_target = '/.velnor-runtime-identity' AND volume_subpath IS 'runtime-identity') OR (mount_target = '/opt/velnor/job-facts' AND volume_subpath IS 'job-facts'))) OR (role = 'runner-home' AND ((observer IN ('runner', 'dind') AND mount_target = '/home/runner' AND volume_subpath IS NULL) OR (observer = 'runner' AND mount_target = '/opt/velnor/source-proof/inbox' AND volume_subpath IS NOT NULL AND volume_subpath IS 'source-proof/inbox'))) OR (role = 'engine-metadata' AND observer = 'probe' AND volume_subpath IS NULL) OR (role != 'engine-metadata' AND role != 'runner-home' AND volume_subpath IS NULL)));
