END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_reservation_guard BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.reservation_id != NEW.reservation_id BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_name_guard BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.container_name != NEW.container_name BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_unclaimed_transition BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.create_state = 'unclaimed' AND NOT ((OLD.create_state = NEW.create_state AND OLD.container_id IS NEW.container_id AND OLD.start_state = NEW.start_state) OR (OLD.create_state = 'unclaimed' AND NEW.create_state = 'requested' AND NEW.container_id IS NULL AND NEW.start_state = 'not_requested')) BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_requested_transition BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.create_state = 'requested' AND NOT ((OLD.create_state = NEW.create_state AND OLD.container_id IS NEW.container_id AND OLD.start_state = NEW.start_state) OR (OLD.create_state = 'requested' AND NEW.create_state = 'created' AND NEW.container_id IS NOT NULL AND NEW.start_state = 'not_requested') OR (OLD.create_state = 'requested' AND NEW.create_state = 'uncertain' AND NEW.container_id IS NULL AND NEW.start_state = 'not_requested')) BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_created_transition BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.create_state = 'created' AND NOT ((OLD.create_state = NEW.create_state AND OLD.container_id IS NEW.container_id AND OLD.start_state = NEW.start_state) OR (OLD.create_state = 'created' AND OLD.container_id = NEW.container_id AND ((OLD.start_state = 'not_requested' AND NEW.start_state = 'requested') OR (OLD.start_state = 'requested' AND NEW.start_state IN ('started', 'uncertain'))))) BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
CREATE TRIGGER IF NOT EXISTS provisioning_container_uncertain_transition BEFORE UPDATE ON capacity_reservation_bootstrap_containers WHEN OLD.create_state = 'uncertain' AND NOT (OLD.create_state = NEW.create_state AND OLD.container_id IS NEW.container_id AND OLD.start_state = NEW.start_state) BEGIN
SELECT RAISE (ABORT, 'invalid bootstrap transition');
END;
