CREATE TRIGGER IF NOT EXISTS metadata_probe_cleanup_insert_guard BEFORE INSERT ON capacity_reservation_metadata_probe_cleanups WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_metadata_settlement_claims AS claim JOIN resource_probe_operations AS probe ON probe.operation_id = claim.probe_operation_id JOIN host_operation_leases AS lease ON lease.singleton = 1 AND lease.operation_id = probe.operation_id WHERE claim.reservation_id = NEW.reservation_id AND claim.generation = NEW.generation AND claim.probe_operation_id = NEW.probe_operation_id AND claim.engine_id = NEW.engine_id AND claim.docker_root_digest = NEW.docker_root_digest AND probe.phase = 'removed' AND probe.engine_id = NEW.engine_id AND probe.docker_root_digest = NEW.docker_root_digest AND probe.operation_name = NEW.operation_name AND probe.container_id = NEW.container_id AND NEW.phase = 'removed' AND lease.state = 'released' AND lease.engine_id = NEW.engine_id AND lease.docker_root_digest = NEW.docker_root_digest AND lease.operation_name = NEW.operation_name AND lease.container_id = NEW.container_id AND NEW.lease_released = 1) BEGIN
SELECT RAISE (ABORT, 'invalid linked probe cleanup');
END;
CREATE TRIGGER IF NOT EXISTS metadata_settlement_insert_guard BEFORE INSERT ON capacity_reservation_metadata_settlements WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_metadata_settlement_claims AS claim JOIN capacity_reservation_metadata_probe_cleanups AS cleanup ON cleanup.reservation_id = claim.reservation_id AND cleanup.generation = claim.generation JOIN host_storage_profile_current AS current_profile ON current_profile.singleton = 1 AND current_profile.generation_id = claim.profile_generation_id WHERE claim.reservation_id = NEW.reservation_id AND claim.generation = NEW.generation AND claim.probe_operation_id = NEW.probe_operation_id AND NEW.sample_generation_id = claim.probe_operation_id AND NEW.profile_generation_id = claim.profile_generation_id AND NEW.profile_digest = claim.profile_digest AND NEW.engine_id = claim.engine_id AND NEW.docker_root_digest = claim.docker_root_digest AND cleanup.probe_operation_id = NEW.probe_operation_id AND current_profile.generation_id = NEW.profile_generation_id) BEGIN
SELECT RAISE (ABORT, 'invalid metadata settlement');
END;
CREATE TRIGGER IF NOT EXISTS metadata_pool_insert_guard BEFORE INSERT ON capacity_reservation_metadata_settlement_pools WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_metadata_settlements AS settlement JOIN capacity_reservation_metadata_settlement_claims AS claim ON claim.reservation_id = settlement.reservation_id AND claim.generation = settlement.generation JOIN host_storage_profile_pools AS policy ON policy.generation_id = claim.profile_generation_id AND policy.pool_id = NEW.pool_id JOIN capacity_reservation_provisioning_pools AS held ON held.reservation_id = NEW.reservation_id AND held.pool_id = NEW.pool_id AND held.scope = 'shared-disk' WHERE settlement.reservation_id = NEW.reservation_id AND settlement.generation = NEW.generation AND policy.medium = 'disk' AND policy.inode_policy = NEW.inode_policy AND held.filesystem_instance_digest = NEW.filesystem_instance_digest AND NEW.total_bytes > 0 AND (policy.inode_policy != 'finite' OR NEW.total_inodes > 0) AND (policy.inode_policy != 'dynamic-btrfs' OR (NEW.filesystem_kind = 'btrfs' AND NEW.total_inodes = 0 AND NEW.available_inodes = 0))) BEGIN
SELECT RAISE (ABORT, 'invalid sampled storage pool');
END;
