CREATE TRIGGER IF NOT EXISTS connection_request_reservations_insert_guard BEFORE INSERT ON connection_request_reservations WHEN NOT EXISTS (SELECT 1 FROM connection_request_authorizations AS auth JOIN capacity_reservations AS reservation ON reservation.id = NEW.reservation_id JOIN connection_intents AS intent ON intent.id = reservation.intent_id JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id AND provisioning.operation_id = intent.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id WHERE auth.connection_id = NEW.connection_id AND auth.scale_set_id = NEW.scale_set_id AND auth.request_id = NEW.request_id AND auth.acquire_state = 'requested' AND auth.started_event_digest IS NULL AND auth.completed_event_digest IS NULL AND auth.binding_digest = NEW.binding_digest AND reservation.state = 'reserved' AND reservation.connection_id = NEW.connection_id AND reservation.binding_digest = NEW.binding_digest AND reservation.assignment_key = 'v1|' || NEW.connection_id || '|' || NEW.scale_set_id || '|remote|6:runner|32:' || NEW.physical_nonce AND intent.connection_id = NEW.connection_id AND intent.scale_set_id = NEW.scale_set_id AND intent.kind = 'launch' AND intent.state = 'pending' AND intent.cleanup_proven = 0 AND intent.assignment_key = reservation.assignment_key AND intent.runner_name = 'v' || NEW.physical_nonce AND intent.runner_request_id IS NULL AND intent.acquire_attempted = 0 AND intent.jit_requested = 0 AND intent.docker_id IS NULL AND intent.dind_id IS NULL AND intent.worker_volume IS NULL AND intent.launch_phase = 'provisioning_held' AND state.bootstrap_start_state = 'not_requested') BEGIN
