CREATE TRIGGER IF NOT EXISTS doctor_probe_transition_guard BEFORE UPDATE ON doctor_probe_requests WHEN OLD.request_id != NEW.request_id OR OLD.nonce != NEW.nonce OR OLD.instance_id != NEW.instance_id OR OLD.engine_id != NEW.engine_id OR OLD.docker_root_digest != NEW.docker_root_digest OR OLD.active_slot != NEW.active_slot OR (OLD.child_operation_id IS NOT NEW.child_operation_id AND NOT (OLD.state = 'queued' AND NEW.state = 'running' AND OLD.child_operation_id IS NULL AND NEW.child_operation_id IS NOT NULL)) OR (OLD.state != NEW.state AND NOT ((OLD.state = 'queued' AND NEW.state IN ('running', 'failed')) OR (OLD.state = 'running' AND NEW.state IN ('recovering', 'uncertain', 'completed', 'failed', 'stale')) OR (OLD.state = 'recovering' AND NEW.state IN ('uncertain', 'completed', 'failed', 'stale')) OR (OLD.state = 'uncertain' AND NEW.state = 'recovering') OR (OLD.state = 'completed' AND NEW.state = 'stale'))) BEGIN
