d = 'launch' AND p.engine_id = NEW.engine_id AND p.docker_root_digest = NEW.docker_root_digest AND p.profile_generation_id = NEW.profile_generation_id AND p.profile_digest = NEW.profile_digest AND s.resources_bound = 1 AND s.storage_cleanup_proven = 1 AND s.instance_binding_digest = NEW.instance_binding_digest AND s.jit_state IN ('not_requested', 'cleaned') AND c.instance_binding_digest = NEW.instance_binding_digest AND probe.instance_id = NEW.instance_id AND probe.engine_id = NEW.engine_id AND probe.docker_root_digest = NEW.docker_root_digest AND probe.phase = 'prepared' AND lease.state = 'reserved' AND lease.engine_id = NEW.engine_id AND lease.docker_root_digest = NEW.docker_root_digest AND current_profile.generation_id = NEW.profile_generation_id) BEGIN
