CREATE TRIGGER IF NOT EXISTS storage_initialization_abort_lease_guard BEFORE UPDATE OF abort_lease_until ON capacity_reservation_storage_initialization WHEN NEW.abort_lease_until != OLD.abort_lease_until AND NOT ((NEW.abort_lease_until > OLD.abort_lease_until AND NEW.abort_lease_until > 0 AND NEW.abort_claim_generation > 0) OR (NEW.abort_lease_until = 0 AND NEW.abort_state IN ('absent', 'uncertain'))) BEGIN
SELECT RAISE (ABORT, 'The storage initializer state change is incorrect.');
END;
CREATE TRIGGER IF NOT EXISTS storage_initialization_abort_phase_guard BEFORE UPDATE OF abort_state ON capacity_reservation_storage_initialization WHEN (NEW.abort_state = 'requested' AND (NEW.abort_claim_generation = 0 OR NEW.abort_lease_until = 0)) OR (NEW.abort_state != 'not_requested' AND (NEW.create_state NOT IN ('requested', 'response_recorded', 'created', 'uncertain') OR NEW.start_state NOT IN ('not_requested', 'requested', 'started', 'uncertain') OR NEW.result_state NOT IN ('not_requested', 'confirmed', 'uncertain') OR NEW.remove_state NOT IN ('not_requested', 'requested', 'removed', 'uncertain'))) BEGIN
SELECT RAISE (ABORT, 'The storage initializer state change is incorrect.');
END;
CREATE TRIGGER IF NOT EXISTS storage_initialization_remove_transition_guard BEFORE UPDATE OF remove_state ON capacity_reservation_storage_initialization WHEN NOT ((OLD.remove_state = 'not_requested' AND NEW.remove_state = 'requested') OR (OLD.remove_state = 'requested' AND NEW.remove_state IN ('removed', 'uncertain')) OR OLD.remove_state = NEW.remove_state) OR (OLD.remove_state = 'uncertain' AND NEW.remove_state != 'uncertain') OR (NEW.remove_state != 'not_requested' AND NEW.result_state != 'confirmed') OR (NEW.remove_state = 'removed' AND NEW.helper_id IS NULL) BEGIN
SELECT RAISE (ABORT, 'The storage initializer state change is incorrect.');
END;
