CREATE TRIGGER IF NOT EXISTS reservation_network_insert_guard BEFORE INSERT ON capacity_reservation_networks WHEN NEW.network_name != (SELECT 'velnor-' || i.runner_name || '-private' FROM connection_intents AS i WHERE i.id = NEW.operation_id AND i.connection_id = NEW.connection_id) OR NEW.labels_json != '{"io.velnor.connection-id":"' || NEW.connection_id || '","io.velnor.engine-id":"' || NEW.engine_id || '","io.velnor.managed":"true","io.velnor.operation-id":"' || NEW.operation_id || '","io.velnor.reservation-id":"' || NEW.reservation_id || '"}' OR NOT EXISTS (SELECT 1 FROM capacity_reservations AS r JOIN connection_intents AS i ON i.id = r.intent_id AND i.connection_id = r.connection_id JOIN capacity_reservation_provisioning AS p ON p.reservation_id = r.id WHERE r.id = NEW.reservation_id AND r.connection_id = NEW.connection_id AND r.intent_id = NEW.operation_id AND p.operation_id = NEW.operation_id AND p.engine_id = NEW.engine_id AND p.docker_root_digest = NEW.docker_root_digest AND r.state = 'reserved' AND i.kind = 'launch' AND i.state = 'pending' AND i.cleanup_proven = 0) BEGIN
SELECT RAISE (ABORT, 'invalid private network claim');
END;
