CREATE TRIGGER IF NOT EXISTS reservation_network_transition BEFORE UPDATE ON capacity_reservation_networks WHEN NOT ((OLD.create_state = NEW.create_state AND OLD.network_id IS NEW.network_id) OR (OLD.create_state = 'requested' AND NEW.create_state IN ('created', 'uncertain')) OR (OLD.create_state = 'uncertain' AND NEW.create_state = 'created')) OR NOT ((OLD.remove_state = NEW.remove_state) OR (OLD.remove_state = 'not_requested' AND NEW.remove_state = 'requested') OR (OLD.remove_state = 'not_requested' AND NEW.remove_state = 'removed' AND NEW.create_state IN ('requested', 'uncertain')) OR (OLD.remove_state = 'requested' AND NEW.remove_state IN ('removed', 'uncertain')) OR (OLD.remove_state = 'uncertain' AND NEW.remove_state = 'removed')) BEGIN
SELECT RAISE (ABORT, 'invalid private network state change');
END;
CREATE TRIGGER IF NOT EXISTS reservation_network_start_guard BEFORE UPDATE OF bootstrap_start_state ON capacity_reservation_provisioning_state WHEN OLD.bootstrap_start_state != 'started' AND NEW.bootstrap_start_state = 'started' AND EXISTS (SELECT 1 FROM connection_request_reservations AS request_link WHERE request_link.reservation_id = NEW.reservation_id) AND NOT EXISTS (SELECT 1 FROM capacity_reservation_networks AS n WHERE n.reservation_id = NEW.reservation_id AND n.create_state = 'created' AND n.remove_state = 'not_requested' AND n.network_id IS NOT NULL) BEGIN
