CREATE TRIGGER IF NOT EXISTS storage_initialization_v2_result_guard BEFORE UPDATE OF metadata_layout_digest, result_state ON capacity_reservation_storage_initialization WHEN (NEW.layout_version = 1 AND NEW.metadata_layout_digest IS NOT NULL) OR (NEW.layout_version = 2 AND ((NEW.result_state = 'confirmed' AND (NEW.metadata_layout_digest IS NULL OR length (NEW.metadata_layout_digest) != 64 OR NEW.metadata_layout_digest GLOB '*[^0-9a-f]*')) OR (NEW.result_state != 'confirmed' AND NEW.metadata_layout_digest IS NOT NULL))) OR (OLD.metadata_layout_digest IS NOT NULL AND OLD.metadata_layout_digest IS NOT NEW.metadata_layout_digest) BEGIN
SELECT RAISE (ABORT, 'The storage initializer result is incorrect.');
END;
CREATE TRIGGER IF NOT EXISTS root_backing_insert_guard BEFORE INSERT ON capacity_reservation_root_backing_mappings WHEN NOT EXISTS (SELECT 1 FROM capacity_reservations AS r JOIN capacity_reservation_provisioning AS p ON p.reservation_id = r.id JOIN capacity_reservation_provisioning_state AS s ON s.reservation_id = r.id JOIN connection_intents AS i ON i.id = p.operation_id WHERE r.id = NEW.reservation_id AND r.connection_id = NEW.connection_id AND r.intent_id = NEW.operation_id AND p.operation_id = NEW.operation_id AND p.engine_id = NEW.engine_id AND p.docker_root_digest = NEW.docker_root_digest AND p.sample_generation_id = NEW.sample_generation_id AND s.bootstrap_start_state = 'started' AND s.resources_bound = 0 AND i.state = 'pending' AND i.cleanup_proven = 0) OR NOT EXISTS (SELECT 1 FROM capacity_reservation_bootstrap_containers AS c WHERE c.reservation_id = NEW.reservation_id AND c.role = CASE NEW.role WHEN 'runner-root' THEN 'runner' ELSE 'dind' END AND c.create_state = 'created' AND c.start_state = 'started' AND c.container_id = NEW.container_id) OR length (NEW.logical_filesystem_digest) != 64 OR NEW.logical_filesystem_digest GLOB '*[^0-9a-f]*' OR length (NEW.backing_filesystem_digest) != 64 OR NEW.backing_filesystem_digest GLOB '*[^0-9a-f]*' OR length (NEW.mapping_digest) != 64 OR NEW.mapping_digest GLOB '*[^0-9a-f]*' BEGIN
