CREATE TRIGGER IF NOT EXISTS storage_handoff_insert_guard BEFORE INSERT ON capacity_reservation_storage_handoffs WHEN NOT EXISTS (SELECT 1 FROM capacity_reservation_storage_initialization AS init JOIN capacity_reservations AS reservation ON reservation.id = init.reservation_id JOIN capacity_reservation_provisioning_objects AS object ON object.reservation_id = init.reservation_id AND object.role = 'engine-metadata' AND object.create_state = 'created' WHERE init.reservation_id = NEW.reservation_id AND init.connection_id = NEW.connection_id AND init.operation_id = NEW.operation_id AND init.generation = NEW.generation AND init.create_state = 'created' AND init.start_state = 'started' AND init.result_state = 'confirmed' AND init.remove_state = 'not_requested' AND init.layout_version = 2 AND init.helper_name = NEW.helper_name AND init.helper_id = NEW.helper_id AND init.engine_id = NEW.engine_id AND init.docker_root_digest = NEW.docker_root_digest AND init.metadata_volume = NEW.metadata_volume_name AND init.metadata_volume_id = NEW.metadata_volume_id AND init.operation_key = NEW.operation_key AND init.metadata_layout_digest = NEW.layout_digest AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.state = 'reserved' AND object.docker_name = NEW.metadata_volume_name AND object.docker_id = NEW.metadata_volume_id) OR NEW.state != 'ready_held' BEGIN
SELECT RAISE (ABORT, 'Invalid storage handoff.');
END;
CREATE TRIGGER IF NOT EXISTS storage_handoff_no_delete BEFORE DELETE ON capacity_reservation_storage_handoffs BEGIN
SELECT RAISE (ABORT, 'Keep the storage handoff record.');
