CREATE TRIGGER IF NOT EXISTS storage_initializer_remove_requires_handoff BEFORE UPDATE OF remove_state ON capacity_reservation_storage_initialization WHEN NEW.remove_state = 'requested' AND OLD.result_state = 'confirmed' AND NOT EXISTS (SELECT 1 FROM capacity_reservation_storage_handoffs AS handoff WHERE handoff.reservation_id = NEW.reservation_id AND handoff.connection_id = NEW.connection_id AND handoff.operation_id = NEW.operation_id AND handoff.state = 'attached') BEGIN
