END;
CREATE TRIGGER IF NOT EXISTS storage_handoff_transition_guard BEFORE UPDATE ON capacity_reservation_storage_handoffs WHEN OLD.state != 'ready_held' OR NEW.state != 'attached' OR OLD.reservation_id != NEW.reservation_id OR OLD.connection_id != NEW.connection_id OR OLD.operation_id != NEW.operation_id OR OLD.generation != NEW.generation OR OLD.helper_name != NEW.helper_name OR OLD.helper_id != NEW.helper_id OR OLD.engine_id != NEW.engine_id OR OLD.docker_root_digest != NEW.docker_root_digest OR OLD.metadata_volume_name != NEW.metadata_volume_name OR OLD.metadata_volume_id != NEW.metadata_volume_id OR OLD.operation_key != NEW.operation_key OR OLD.layout_digest != NEW.layout_digest OR OLD.ready_digest != NEW.ready_digest OR NEW.mount_evidence_digest IS NULL BEGIN
SELECT RAISE (ABORT, 'Invalid storage handoff.');
END;
CREATE TRIGGER IF NOT EXISTS storage_handoff_runner_identity_guard BEFORE UPDATE ON capacity_reservation_storage_handoffs WHEN OLD.state = 'ready_held' AND NEW.state = 'attached' AND NOT EXISTS (SELECT 1 FROM capacity_reservation_bootstrap_containers AS runner WHERE runner.reservation_id = NEW.reservation_id AND runner.role = 'runner' AND runner.create_state = 'created' AND runner.start_state = 'started' AND runner.container_id = NEW.runner_container_id) BEGIN
SELECT RAISE (ABORT, 'Invalid storage handoff runner.');
END;
CREATE TRIGGER IF NOT EXISTS storage_handoff_dind_identity_guard BEFORE UPDATE ON capacity_reservation_storage_handoffs WHEN OLD.state = 'ready_held' AND NEW.state = 'attached' AND NOT EXISTS (SELECT 1 FROM capacity_reservation_bootstrap_containers AS dind WHERE dind.reservation_id = NEW.reservation_id AND dind.role = 'dind' AND dind.create_state = 'created' AND dind.start_state = 'started' AND dind.container_id = NEW.dind_container_id) BEGIN
SELECT RAISE (ABORT, 'Invalid storage handoff DinD.');
END;
CREATE TRIGGER IF NOT EXISTS storage_initialization_v2_insert_guard BEFORE INSERT ON capacity_reservation_storage_initialization WHEN (NEW.layout_version = 1 AND (NEW.metadata_volume IS NOT NULL OR NEW.metadata_volume_id IS NOT NULL OR NEW.metadata_layout_digest IS NOT NULL)) OR (NEW.layout_version = 2 AND (NEW.metadata_volume IS NULL OR NEW.metadata_volume_id IS NULL OR NEW.metadata_volume != NEW.metadata_volume_id OR length (NEW.metadata_volume) != 42 OR substr (NEW.metadata_volume, 1, 1) != 'w' OR substr (NEW.metadata_volume, 34) != '-metadata' OR substr (NEW.metadata_volume, 2, 32) GLOB '*[^0-9a-f]*' OR (SELECT COUNT (*) FROM capacity_reservation_provisioning_objects WHERE reservation_id = NEW.reservation_id AND role = 'engine-metadata' AND create_state = 'created' AND docker_id = NEW.metadata_volume_id AND docker_name = NEW.metadata_volume) != 1)) BEGIN
SELECT RAISE (ABORT, 'The storage initializer record is incorrect.');
END;
CREATE TRIGGER IF NOT EXISTS execution_publication_context_insert_guard BEFORE INSERT ON execution_publication_operations WHEN NOT EXISTS (SELECT 1 FROM resource_probe_operations AS operation JOIN host_operation_leases AS lease ON lease.singleton = 1 AND lease.operation_id = operation.operation_id JOIN capacity_reservation_storage_initialization AS metadata ON metadata.reservation_id = NEW.reservation_id JOIN capacity_reservation_provisioning_state AS worker_state ON worker_state.reservation_id = NEW.reservation_id LEFT OUTER JOIN connection_execution_proofs AS proof ON proof.intent_id = NEW.parent_operation_id WHERE operation.operation_id = NEW.operation_id AND operation.helper_role = 'execution-publication' AND operation.role = 'resource-probe' AND operation.probe_purpose = 'none' AND operation.request_sha256 IS NULL AND operation.phase = 'prepared' AND operation.container_id IS NULL AND operation.operation_name = 'velnor-execution-publication-' || operation.operation_id AND operation.projection_digest = NEW.projection_digest AND lease.state = 'reserved' AND lease.container_id IS NULL AND lease.operation_name = operation.operation_name AND lease.engine_id = operation.engine_id AND lease.docker_root_digest = operation.docker_root_digest AND metadata.layout_version = 2 AND metadata.result_state = 'confirmed' AND metadata.metadata_volume = NEW.metadata_volume_name AND metadata.metadata_volume_id = NEW.metadata_volume_id AND metadata.metadata_layout_digest = NEW.metadata_layout_digest AND worker_state.resources_bound = 1 AND worker_state.guest_boot_id = NEW.guest_boot_id AND NEW.recovery_projection_json IS NOT NULL AND NEW.recovery_projection_sha256 IS NOT NULL AND ((NEW.parent_kind = 'challenge' AND proof.reservation_id = NEW.reservation_id AND proof.connection_id = NEW.connection_id AND proof.scale_set_id = NEW.scale_set_id AND proof.witness_request_id = NEW.witness_request_id AND proof.runner_id = NEW.runner_id AND proof.runner_name = NEW.runner_name AND proof.runner_container_id = NEW.runner_container_id AND proof.dind_container_id = NEW.dind_container_id AND proof.engine_id = NEW.engine_id AND proof.docker_root_digest = NEW.docker_root_digest AND NEW.actual_request_id IS NULL AND proof.challenge_state = 'requested' AND proof.challenge_digest = NEW.claim_digest AND proof.challenge_digest = NEW.payload_sha256) OR (NEW.parent_kind = 'decision' AND proof.reservation_id = NEW.reservation_id AND proof.connection_id = NEW.connection_id AND proof.scale_set_id = NEW.scale_set_id AND proof.witness_request_id = NEW.witness_request_id AND proof.runner_id = NEW.runner_id AND proof.runner_name = NEW.runner_name AND proof.runner_container_id = NEW.runner_container_id AND proof.dind_container_id = NEW.dind_container_id AND proof.engine_id = NEW.engine_id AND proof.docker_root_digest = NEW.docker_root_digest AND proof.actual_request_id = NEW.actual_request_id AND proof.proof_state IN ('approved', 'denied') AND EXISTS (SELECT 1 FROM connection_execution_decisions AS decision WHERE decision.intent_id = NEW.parent_operation_id AND decision.reservation_id = NEW.reservation_id AND decision.connection_id = NEW.connection_id AND decision.scale_set_id = NEW.scale_set_id AND decision.witness_request_id = NEW.witness_request_id AND decision.actual_request_id = NEW.actual_request_id AND decision.decision_digest = NEW.claim_digest AND decision.decision_digest = NEW.payload_sha256 AND decision.delivery_state = 'requested')) OR (NEW.parent_kind = 'job-facts' AND NEW.witness_request_id IS NULL AND NEW.actual_request_id IS NULL AND EXISTS (SELECT 1 FROM capacity_reservations AS reservation JOIN connection_intents AS intent ON intent.id = reservation.intent_id JOIN connection_runner_jits AS jit ON jit.intent_id = intent.id AND jit.connection_id = intent.connection_id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id WHERE reservation.id = NEW.reservation_id AND reservation.connection_id = NEW.connection_id AND reservation.state = 'reserved' AND intent.connection_id = NEW.connection_id AND intent.state = 'pending' AND intent.cleanup_proven = 0 AND intent.launch_phase = 'jit_bound' AND state.reservation_id = NEW.reservation_id AND state.resources_bound = 1 AND state.bootstrap_start_state = 'started' AND state.jit_state = 'bound' AND state.publication_state = 'requested' AND state.delivery_state = 'not_requested' AND state.storage_cleanup_proven = 0 AND state.runner_id = NEW.runner_id AND state.runner_name = NEW.runner_name AND state.runner_scale_set_id = NEW.scale_set_id AND state.runner_container_id = NEW.runner_container_id AND state.dind_container_id = NEW.dind_container_id AND state.guest_boot_id = NEW.guest_boot_id AND jit.state = 'bound' AND jit.runner_id = NEW.runner_id AND jit.runner_name = NEW.runner_name AND jit.scale_set_id = NEW.scale_set_id)))) BEGIN
SELECT RAISE (ABORT, 'invalid execution publication context');
END;
