CREATE TRIGGER IF NOT EXISTS cleanup_observer_witness_insert_guard BEFORE INSERT ON capacity_reservation_cleanup_observer_witnesses WHEN NOT EXISTS (SELECT 1 FROM capacity_reservations AS reservation JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id JOIN connection_intents AS intent ON intent.id = provisioning.operation_id AND intent.connection_id = reservation.connection_id WHERE reservation.id = NEW.reservation_id AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND reservation.engine_id = NEW.engine_id AND reservation.docker_root_digest = NEW.docker_root_digest AND reservation.state = 'reserved' AND intent.kind = 'launch' AND intent.state = 'pending' AND intent.cleanup_proven = 0 AND intent.launch_phase = 'bootstrap_started' AND provisioning.operation_id = NEW.operation_id AND state.bootstrap_start_state = 'started' AND state.runner_container_id = NEW.runner_container_id AND state.dind_container_id = NEW.dind_container_id AND state.resources_bound = 0 AND state.instance_binding_digest IS NULL AND state.jit_state = 'not_requested' AND state.guest_boot_id IS NULL) BEGIN
