CREATE TRIGGER IF NOT EXISTS cleanup_observer_jit_guard BEFORE UPDATE OF jit_state ON capacity_reservation_provisioning_state WHEN OLD.jit_state = 'not_requested' AND NEW.jit_state = 'requested' AND OLD.resources_bound = 1 AND NOT EXISTS (SELECT 1 FROM capacity_reservation_cleanup_observer_witnesses AS witness WHERE witness.reservation_id = NEW.reservation_id AND witness.instance_binding_digest = NEW.instance_binding_digest AND witness.guest_boot_id = NEW.guest_boot_id AND witness.runner_container_id = NEW.runner_container_id AND witness.dind_container_id = NEW.dind_container_id) BEGIN
SELECT RAISE (ABORT, 'cleanup observer witness is required');
END;
CREATE TRIGGER IF NOT EXISTS cleanup_observer_probe_insert_guard BEFORE INSERT ON capacity_reservation_cleanup_observer_probes WHEN NOT EXISTS (SELECT 1 FROM resource_probe_operations AS probe JOIN host_operation_leases AS lease ON lease.singleton = 1 AND lease.operation_id = probe.operation_id JOIN capacity_reservation_cleanup_observer_witnesses AS witness ON witness.reservation_id = NEW.reservation_id JOIN capacity_reservations AS reservation ON reservation.id = witness.reservation_id JOIN capacity_reservation_provisioning AS provisioning ON provisioning.reservation_id = reservation.id JOIN capacity_reservation_provisioning_state AS state ON state.reservation_id = reservation.id WHERE probe.operation_id = NEW.probe_operation_id AND probe.helper_role = 'resource-probe' AND probe.role = 'resource-probe' AND probe.probe_purpose = 'cleanup-observer' AND probe.request_sha256 IS NOT NULL AND probe.request_context IS NOT NULL AND probe.phase = 'prepared' AND probe.container_id IS NULL AND probe.engine_id = witness.engine_id AND probe.docker_root_digest = witness.docker_root_digest AND lease.state = 'reserved' AND lease.engine_id = probe.engine_id AND lease.docker_root_digest = probe.docker_root_digest AND reservation.state IN ('reserved', 'uncertain') AND reservation.connection_id = NEW.connection_id AND reservation.intent_id = NEW.operation_id AND witness.connection_id = NEW.connection_id AND witness.operation_id = NEW.operation_id AND witness.binding_sha256 = NEW.binding_sha256 AND provisioning.operation_id = NEW.operation_id AND state.resources_bound = 1 AND state.storage_cleanup_proven = 0 AND state.instance_binding_digest = witness.instance_binding_digest AND state.guest_boot_id = witness.guest_boot_id AND state.runner_container_id = witness.runner_container_id AND state.dind_container_id = witness.dind_container_id) BEGIN
SELECT RAISE (ABORT, 'invalid cleanup observer probe binding');
END;
CREATE TRIGGER IF NOT EXISTS cleanup_observer_probe_no_update BEFORE UPDATE ON capacity_reservation_cleanup_observer_probes BEGIN
SELECT RAISE (ABORT, 'cleanup observer probe binding is immutable');
END;
CREATE TRIGGER IF NOT EXISTS cleanup_observer_probe_no_delete BEFORE DELETE ON capacity_reservation_cleanup_observer_probes BEGIN
SELECT RAISE (ABORT, 'cleanup observer probe binding is retained');
