CREATE INDEX IF NOT EXISTS doctor_probe_state ON doctor_probe_requests (state, request_id);
CREATE UNIQUE INDEX IF NOT EXISTS execution_actual_request ON connection_execution_proofs (connection_id, scale_set_id, actual_request_id) WHERE actual_request_id IS NOT NULL;
COMMIT;
